




"use strict";

const RuntimeGlobals = require("../RuntimeGlobals");
const { equals } = require("../util/ArrayHelpers");
const makeSerializable = require("../util/makeSerializable");
const { propertyAccess } = require("../util/property");
const { getConcatenatedExportAccess } = require("./CommonJsDependencyHelpers");
const NullDependency = require("./NullDependency");













class CommonJsSelfReferenceDependency extends NullDependency {
	






	constructor(range, base, names, call) {
		super();
		this.range = range;
		
		this.base = base;
		
		this.names = names;
		
		this.call = call;
	}

	get type() {
		return "cjs self exports reference";
	}

	get category() {
		return "self";
	}

	



	getResourceIdentifier() {
		return "self";
	}

	





	getReferencedExports(moduleGraph, runtime) {
		return [this.call ? this.names.slice(0, -1) : this.names];
	}

	



	serialize(context) {
		context
			.write(this.range)
			.write(this.base)
			.write(this.names)
			.write(this.call);
		super.serialize(context);
	}

	



	deserialize(context) {
		this.range = context.read();
		const c1 = context.rest;
		this.base = c1.read();
		const c2 = c1.rest;
		this.names = c2.read();
		const c3 = c2.rest;
		this.call = c3.read();
		super.deserialize(c3.rest);
	}
}

makeSerializable(
	CommonJsSelfReferenceDependency,
	"webpack/lib/dependencies/CommonJsSelfReferenceDependency"
);

CommonJsSelfReferenceDependency.Template = class CommonJsSelfReferenceDependencyTemplate extends (
	NullDependency.Template
) {
	






	apply(
		dependency,
		source,
		{
			module,
			moduleGraph,
			runtime,
			runtimeRequirements,
			initFragments,
			concatenationScope
		}
	) {
		const dep =  (dependency);
		
		const used =
			dep.names.length === 0
				? dep.names
				:  (
						moduleGraph.getExportsInfo(module).getUsedName(dep.names, runtime)
					);
		if (!used) {
			throw new Error(
				"Self-reference dependency has unused export name: This should not happen"
			);
		}

		if (concatenationScope) {
			
			
			if (
				dep.names.length === 0 ||
				(dep.base !== "exports" && dep.base !== "module.exports")
			) {
				throw new Error(
					`Unsupported self-reference ${dep.base} in concatenated CommonJS module`
				);
			}
			source.replace(
				dep.range[0],
				dep.range[1] - 1,
				getConcatenatedExportAccess(
					concatenationScope,
					initFragments,
					dep.names
				)
			);
			return;
		}

		
		let base;
		switch (dep.base) {
			case "exports":
				runtimeRequirements.add(RuntimeGlobals.exports);
				base = module.exportsArgument;
				break;
			case "module.exports":
				runtimeRequirements.add(RuntimeGlobals.module);
				base = `${module.moduleArgument}.exports`;
				break;
			case "this":
				runtimeRequirements.add(RuntimeGlobals.thisAsExports);
				base = "this";
				break;
			default:
				throw new Error(`Unsupported base ${dep.base}`);
		}

		if (base === dep.base && equals(used, dep.names)) {
			
			
			
			
			return;
		}

		source.replace(
			dep.range[0],
			dep.range[1] - 1,
			`${base}${propertyAccess( (used))}`
		);
	}
};

module.exports = CommonJsSelfReferenceDependency;
